INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-jiqian', '李继迁', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '党项拓跋氏后裔，北宋初年起兵反宋，辗转恢复夏州一带势力，并以灵州为重要据点。其子李德明承接其势力，李继迁被追尊为夏太祖，奠定后来西夏建国基础；在位982—1004年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李继迁"}]'::jsonb, '光天皇帝', '太祖', '夏太祖')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-deming', '李德明', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '李继迁之子，继承定难军及党项李氏势力后与北宋、辽朝往来，受宋册封为西平王。其长期避免全面战争并经营党项政权，扩展李氏控制区，为李元昊称帝建国准备条件；在位1004—1031年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李德明"}]'::jsonb, NULL, NULL, '西夏王')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-yuanhao', '李元昊', ARRAY[]::text[], NULL, NULL, 1003, 1, 1048, 1, ARRAY['皇帝'], '李德明之子，夏景宗，1038年脱离宋朝称帝、定国号大夏，建立西夏。其创制党项文字、改革官制并多次与宋交战，1044年宋夏议和后形成三国鼎立格局；在位1031—1048年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李元昊"}]'::jsonb, '武烈皇帝', '景宗', '夏景宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-liangzuo', '李谅祚', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '李元昊之子，夏毅宗，幼年即位，由没藏太后及其兄没藏讹庞辅政。亲政后调整对宋关系并推动制度建设，后来在宫廷政变后由梁氏家族掌权；在位1048—1067年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李谅祚"}]'::jsonb, '昭英皇帝', '毅宗', '夏毅宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-bingchang', '李秉常', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '夏毅宗之子、夏惠宗，幼年继位后先由梁太后掌政，亲政尝试收回权力时与母后及外戚冲突。宋夏战争反复，梁氏重新控制朝政，他在位期间王权受到外戚牵制；在位1067—1086年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李秉常"}]'::jsonb, '昭简皇帝', '惠宗', '夏惠宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-qianshun', '李乾顺', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '夏惠宗之子、夏崇宗，幼年即位，梁太后长期摄政，后亲政并维持西夏统治。其五十余年在位横跨宋辽对峙、金朝崛起及金灭辽后格局变化，西夏在此期间延续并巩固其国家制度；在位1086—1139年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李乾顺"}]'::jsonb, '康靖皇帝', '崇宗', '夏崇宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-renxiao', '李仁孝', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '夏崇宗之子、夏仁宗，在位期间整顿典章、尊崇儒学并发展学校与科举制度，推动西夏汉文和党项文字文教。其朝与金、南宋保持相对稳定的外交关系，西夏文化发展达到重要阶段；在位1139—1193年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李仁孝"}]'::jsonb, '圣德皇帝', '仁宗', '夏仁宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-chunyou', '李纯佑', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '夏仁宗之子、夏桓宗，承接相对稳定的西夏政局。其在位后期蒙古势力兴起并向西北扩张，1206年被李安全废黜；在位1193—1206年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李纯佑"}]'::jsonb, '昭简皇帝', '桓宗', '夏桓宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-anquan', '李安全', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '夏仁宗侄、夏襄宗，废黜李纯佑后即位，依靠外戚势力执政。蒙古于1209年大举攻夏，西夏被迫求和并承受持续压力；1211年李遵顼发动政变夺位；在位1206—1211年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李安全"}]'::jsonb, '敬穆皇帝', '襄宗', '夏襄宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-zunxu', '李遵顼', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '西夏宗室、夏神宗，以政变推翻李安全后即位。蒙古军持续进攻之际，他一度主动伐金以求缓解压力，却使西夏陷入更不利的外交与军事处境，后传位于子李德旺；在位1211—1223年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李遵顼"}]'::jsonb, '英武皇帝', '神宗', '夏神宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-dewang', '李德旺', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '李遵顼之子、夏献宗，继位时西夏已承受蒙古长期侵攻。其在位期间尝试联合金朝抵抗蒙古，但战局持续恶化，1226年由李睍继位；在位1223—1226年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李德旺"}]'::jsonb, '南平王', '献宗', '夏献宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-xian-xixia', '李睍', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '夏献宗之后继位的西夏末帝李睍，蒙古军攻夏期间即位，统治区域迅速收缩。1227年蒙古军攻灭西夏，他出降后被杀，西夏政权终结；在位1226—1227年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李睍"}]'::jsonb, NULL, NULL, '夏末帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('mo-nang-e-pang', '没藏讹庞', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家','军事家'], '西夏权臣，毅宗朝没藏太后之父，长期摄政干政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/没藏讹庞"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liang-taihou-xixia', '梁太后', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['后妃','政治家'], '惠宗李秉常之母，两度摄政，主张对宋用兵。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁太后"}]'::jsonb, NULL, NULL, NULL)
